-- Retail tariffs are independent of provider costs and of accepted usage attempts.
CREATE TABLE model_pricing_state (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  factory_version TEXT NOT NULL,
  rules_json TEXT NOT NULL CHECK (json_valid(rules_json)),
  change_id TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
INSERT INTO model_pricing_state VALUES (1, 0, 'factory-2026-09-21', '{}', 'factory', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE model_pricing_factory (
  version TEXT NOT NULL,
  configuration_key TEXT NOT NULL,
  baseline_json TEXT NOT NULL CHECK (json_valid(baseline_json)),
  created_at TEXT NOT NULL,
  PRIMARY KEY (version, configuration_key)
);
CREATE TABLE model_pricing_changes (
  revision INTEGER PRIMARY KEY,
  actor_user_id TEXT NOT NULL,
  change_id TEXT NOT NULL UNIQUE,
  model_id TEXT NOT NULL,
  configuration_key TEXT,
  action TEXT NOT NULL CHECK (action IN ('save','reset','reset_model')),
  before_json TEXT NOT NULL CHECK (json_valid(before_json)),
  after_json TEXT NOT NULL CHECK (json_valid(after_json)),
  created_at TEXT NOT NULL
);
CREATE TABLE model_provider_price_observations (
  model_id TEXT PRIMARY KEY,
  source_url TEXT NOT NULL,
  observed_at TEXT NOT NULL,
  content_sha256 TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('review_required','unavailable'))
);

CREATE TRIGGER member_ai_usage_attempts_v2_tariff_revision BEFORE INSERT ON member_ai_usage_attempts_v2
WHEN json_extract(NEW.metadata_json, '$.model_tariff.tariff.revision') IS NOT NULL
AND json_extract(NEW.metadata_json, '$.model_tariff.tariff.revision') != (SELECT revision FROM model_pricing_state WHERE id=1)
BEGIN SELECT RAISE(ABORT, 'model_pricing_stale'); END;

CREATE TRIGGER ai_usage_attempts_v2_tariff_revision BEFORE INSERT ON ai_usage_attempts_v2
WHEN json_extract(NEW.metadata_json, '$.model_tariff.tariff.revision') IS NOT NULL
AND json_extract(NEW.metadata_json, '$.model_tariff.tariff.revision') != (SELECT revision FROM model_pricing_state WHERE id=1)
BEGIN SELECT RAISE(ABORT, 'model_pricing_stale'); END;

CREATE TRIGGER admin_ai_usage_attempts_v2_tariff_revision BEFORE INSERT ON admin_ai_usage_attempts_v2
WHEN json_extract(NEW.budget_policy_json, '$.model_tariff.tariff.revision') IS NOT NULL
AND json_extract(NEW.budget_policy_json, '$.model_tariff.tariff.revision') != (SELECT revision FROM model_pricing_state WHERE id=1)
BEGIN SELECT RAISE(ABORT, 'model_pricing_stale'); END;

CREATE TRIGGER ai_video_jobs_tariff_revision BEFORE INSERT ON ai_video_jobs_v2
WHEN json_extract(NEW.budget_policy_json, '$.model_tariff.tariff.revision') IS NOT NULL
AND json_extract(NEW.budget_policy_json, '$.model_tariff.tariff.revision') != (SELECT revision FROM model_pricing_state WHERE id=1)
BEGIN SELECT RAISE(ABORT, 'model_pricing_stale'); END;

